const open = $('Open requests').first().json;
const requests = Array.isArray(open.requests) ? open.requests : JSON.parse(open.requests || '[]');
return requests.filter((r) => r.state === 'dispatched' && r.dispatched_at)
  .map((r) => ({ json: { ...r, since: new Date(Date.parse(r.dispatched_at) - 120000).toISOString().slice(0, 19) + 'Z' } }));

// The triage run W2 started has the title "triage <nightly run ID>".
const requests = $('Dispatched').all();
return $input.all().flatMap((page, i) => {
  const r = requests[i].json;
  const run = (page.json.workflow_runs ?? [])
    .filter((w) => w.display_title === `triage ${r.nightly_run_id}` && w.created_at >= r.since)
    .sort((a, b) => b.created_at.localeCompare(a.created_at))[0];
  return run && run.status === 'completed'
    ? [{ json: { nightly_run_id: r.nightly_run_id, triage_run_id: String(run.id), repo: $('Settings').first().json.repo,
      run_id: String(run.id), name: 'run-outcome' } }]
    : [];
});

// Which nights to post now: classified (triage ended ok) or the fallback (it
// failed, was blocked or capped, or no run finished within 60 minutes of the
// start, or the gate kept it back for 60 minutes). Others wait.
const WAIT_MS = 60 * 60000;
const now = Date.now();
const open = $('Open requests').first().json;
const requests = Array.isArray(open.requests) ? open.requests : JSON.parse(open.requests || '[]');
const finished = $('Finished runs').isExecuted ? $('Finished runs').all().map((i) => i.json) : [];
const outcomes = $('Read outcome').isExecuted ? $('Read outcome').all().map((i) => i.json) : [];
const result = {};
finished.forEach((f, i) => { result[f.nightly_run_id] = { triage_run_id: f.triage_run_id, outcome: outcomes[i]?.found ? outcomes[i].data : null }; });

return requests.flatMap((r) => {
  if (r.post_wait_until && Date.parse(r.post_wait_until) > now) return [];  // the gate said "not now" to posting
  const base = { nightly_run_id: r.nightly_run_id, posted: Array.isArray(r.posted) ? r.posted : JSON.parse(r.posted || '[]') };
  if (r.state === 'dispatched') {
    const done = result[r.nightly_run_id];
    if (done) {
      const o = done.outcome;
      if (o && o.status === 'ok') return [{ json: { ...base, mode: 'classified', triage_run_id: done.triage_run_id, reason: '' } }];
      return [{ json: { ...base, mode: 'fallback', triage_run_id: done.triage_run_id,
        reason: o ? (o.status === 'error' ? (o.reason || 'error') : o.status === 'blocked' ? (o.reason || 'blocked') : o.status) : 'no-run-outcome' } }];
    }
    if (now - Date.parse(r.dispatched_at) > WAIT_MS) return [{ json: { ...base, mode: 'fallback', triage_run_id: '', reason: 'no-triage-run' } }];
    return [];
  }
  // deferred: the gate kept triage back (AI work off, or the triage limit)
  if (now - Date.parse(r.created_at) > WAIT_MS) {
    return [{ json: { ...base, mode: 'fallback', triage_run_id: '', reason: r.queue_reason === 'capped' ? 'capped' : (r.queue_reason || 'not-started') } }];
  }
  return [];
});

// Posting is a gated action (AR-11): only the nights the gate allows.
const decided = $('Decide').all();
return $input.all().flatMap((answer, i) => (answer.json.allowed === true ? [decided[i]] : []));

// For each night: its failure-list (the S1 thread and the failures) and, when
// classified, the triage result.
const repo = $('Settings').first().json.repo;
return $input.all().flatMap((d) => [
  { json: { repo, run_id: d.json.nightly_run_id, name: 'failure-list' } },
  ...(d.json.mode === 'classified' ? [{ json: { repo, run_id: d.json.triage_run_id, name: 'triage' } }] : []),
]);

// S2 (one per failure, classified), or S3 then one unclassified failure
// message per failure (EXPERIENCE.md M2, M3). All are replies in the S1
// thread. Anything already posted for a night (a retry) is skipped.

// Words copied from contracts/vocabulary.json (triage_class and reactions);
// scripts/tests/test_n8n_workflows.py checks the copy.
const CLASS = { product_defect: 'Product defect', test_defect: 'Test defect', environment: 'Environment', flaky: 'Flaky', unknown: 'Unknown' };
const STATUS = { failed: 'FAILED', quarantined: 'QUARANTINED', 'passed-on-retry': 'PASSED ON RETRY' };
const LEGEND = 'React: 🐞 Bug (file in Jira, you are Reporter) · 🔁 Flaky (quarantine PR) · 🌩️ Environment · '
  + '🙈 Ignore (reply with a reason) · ↩️ Undo within 24 h. Reply appears in about 2 minutes.';
const SUGGESTED = {
  product_defect: 'check the run, then react. Suggested: 🐞 Bug.',
  flaky: 'check the run, then react. Suggested: 🔁 Flaky.',
  environment: 'check the run, then react. Suggested: 🌩️ Environment.',
  test_defect: 'fix the test (the healer in Claude Code on a laptop can help), or react.',
  unknown: 'look at the run, then react.',
};
const WHY = {
  capped: "the agent's daily limit for triage is reached",
  disabled: 'AI work is off', 'agent-enabled-off': 'AI work is off',
  'no-triage-input': "the masked failure details weren't saved",
  'agent-failed': 'the triage run failed', 'agent-not-set-up': "the agent isn't set up yet",
  'invalid-triage': "the classification didn't pass its checks",
  'no-triage-run': 'no triage run finished within 60 minutes',
  'no-run-outcome': "the triage run didn't say how it ended",
  'not-started': "triage wasn't started",
};

const repo = `https://github.com/${$('Settings').first().json.repo}`;
const reads = $('Read artifacts').all().map((i) => i.json);
let next = 0;
return $('Allowed nights').all().flatMap((night) => {
  const d = night.json;
  const list = reads[next++];
  const triage = d.mode === 'classified' ? reads[next++] : null;
  if (!list?.found) return [];  // no failure-list: nothing to reply under
  const fl = list.data;
  const done = new Set(d.posted);
  const runUrl = `${repo}/actions/runs/${fl.nightly_run_id}`;
  const links = [{ label: 'Run', url: runUrl }, { label: 'Allure report', url: `${runUrl}#artifacts` }];
  const shorten = fl.failures.length > 10;
  const name = (id) => (shorten ? id.split('::').pop().split(' > ').pop() : id);
  const classes = Object.fromEntries((triage?.found ? triage.data.failures : []).map((f) => [f.test_id, f]));
  const out = [];
  const base = { nightly_run_id: d.nightly_run_id, thread_ts: fl.slack_ts, todo_label: '', kind: '' };

  if (d.mode === 'fallback' && !done.has('s3')) {
    out.push({ ...base, key: 's3', test_id: '', class: '',
      header: "Classification didn't run for last night's failures.",
      body: `Reason: ${WHY[d.reason] ?? 'triage ended without a result'} (\`${d.reason}\`).`,
      todo: 'work from the list above. A QA member can run triage in Claude Code on a laptop. The gate is unchanged.',
      links: d.triage_run_id ? [{ label: 'Triage run', url: `${repo}/actions/runs/${d.triage_run_id}` }] : [], legend: '' });
  }
  for (const f of fl.failures) {
    if (done.has(`test:${f.test_id}`)) continue;
    const c = classes[f.test_id];
    const where = `\`${name(f.test_id)}\` — flow \`${f.flow_id || 'unknown'}\``;
    if (c) {
      const lines = [where, `Why: ${c.evidence}`];
      if (c.bug_title) lines.push(`Drafted bug: "${c.bug_title}"`);
      out.push({ ...base, key: `test:${f.test_id}`, test_id: f.test_id, class: c.class,
        header: `Class: ${CLASS[c.class]} (suggested)`, body: lines.join('\n'), todo: SUGGESTED[c.class], links, legend: LEGEND });
    } else {
      out.push({ ...base, key: `test:${f.test_id}`, test_id: f.test_id, class: '',
        header: 'Not classified', body: `${where}\nStatus: ${STATUS[f.status] ?? f.status}.`,
        todo: 'look at the run, then react.', links, legend: LEGEND });
    }
  }
  return out.map((m) => ({ json: m }));
});

// What went out (posted, or a preview while Slack isn't set up), to remember
// it; failure messages that really posted also get a message mapping row.
const messages = $('Messages').all();
return $input.all().map((r, i) => ({ json: { ...messages[i].json, ok: Boolean(r.json.posted || r.json.preview),
  channel: r.json.channel ?? '', ts: r.json.ts ?? '', error: r.json.error ?? '' } })).filter((m) => m.json.ok);

// Any message Slack didn't take fails the run (W0 alerts). What did go out is
// remembered, so the retry posts only the rest.
const failed = ($('Post').isExecuted ? $('Post').all() : []).filter((r) => !r.json.posted && !r.json.preview);
if (failed.length) throw new Error(`${failed.length} triage message(s) not posted: ${failed[0].json.error}`);
return $('Allowed nights').all();

return $('Allowed nights').all().map((d) => ({
  json: {
    actor: 'n8n:w3-triage-poster',
    actor_type: 'n8n',
    action: d.json.mode === 'classified' ? 'triage-posted' : 'triage-fallback-posted',
    target: `nightly ${d.json.nightly_run_id}${d.json.reason ? ` (${d.json.reason})` : ''}`,
    link: `https://github.com/${$('Settings').first().json.repo}/actions/runs/${d.json.nightly_run_id}`,
  },
}));
